types.prepare:
const LET = "CDEFGAB", PCS = [0, 2, 4, 5, 7, 9, 11];
const pcOf = (n) => (((PCS[LET.indexOf(n.letter)] + n.acc) % 12) + 12) % 12;
const up = (n, steps, semis) => {
  const li = LET.indexOf(n.letter) + steps;
  const t = { letter: LET[li % 7], acc: 0 };
  t.acc = ((pcOf(n) + semis - PCS[li % 7] + 18) % 12) - 6;
  return t;
};
const ACC = { "-2": "𝄫", "-1": "♭", 0: "", 1: "♯", 2: "𝄪" };
const TEX = { "-2": "{\\flat\\flat}", "-1": "{\\flat}", 0: "", 1: "{\\sharp}", 2: "{\\sharp\\sharp}" };
const txt = (n) => `${n.letter}${ACC[n.acc]}`;
const tex = (n) => `\\mathrm{${n.letter}}${TEX[n.acc]}`;

// quality -> [text suffix, tex suffix, tones as [degree label, letter steps, semitones]]
const Q = {
  maj: ["", "", [["1", 0, 0], ["3", 2, 4], ["5", 4, 7]]],
  min: ["m", "m", [["1", 0, 0], ["♭3", 2, 3], ["5", 4, 7]]],
  dim: ["dim", "^{\\circ}", [["1", 0, 0], ["♭3", 2, 3], ["♭5", 4, 6]]],
  aug: ["aug", "^{+}", [["1", 0, 0], ["3", 2, 4], ["♯5", 4, 8]]],
  sus2: ["sus2", "\\mathrm{sus2}", [["1", 0, 0], ["2", 1, 2], ["5", 4, 7]]],
  sus4: ["sus4", "\\mathrm{sus4}", [["1", 0, 0], ["4", 3, 5], ["5", 4, 7]]],
  maj7: ["maj7", "\\mathrm{maj7}", [["1", 0, 0], ["3", 2, 4], ["5", 4, 7], ["7", 6, 11]]],
  "7": ["7", "^{7}", [["1", 0, 0], ["3", 2, 4], ["5", 4, 7], ["♭7", 6, 10]]],
  m7: ["m7", "\\mathrm{m}^{7}", [["1", 0, 0], ["♭3", 2, 3], ["5", 4, 7], ["♭7", 6, 10]]],
  m7b5: ["m7♭5", "^{\\varnothing 7}", [["1", 0, 0], ["♭3", 2, 3], ["♭5", 4, 6], ["♭7", 6, 10]]],
  dim7: ["dim7", "^{\\circ 7}", [["1", 0, 0], ["♭3", 2, 3], ["♭5", 4, 6], ["𝄫7", 6, 9]]],
};
const style = String(fields.style ?? "").trim().toLowerCase() || "block";
if (!["block", "arpeggio", "both"].includes(style)) throw new Error(`style must be block, arpeggio or both (got "${fields.style}")`);
const NAMES = { maj: "major", min: "minor", dim: "diminished", aug: "augmented", sus2: "sus2", sus4: "sus4", maj7: "maj7", "7": "dom7", m7: "m7", m7b5: "m7♭5", dim7: "dim7" };
let pool = (Array.isArray(fields.qualities) ? fields.qualities : []).filter((q) => Q[q]);
if (!pool.length) pool = ["maj", "min"];
const quality = rng.pick(pool);
const [sfx, qtex, tones] = Q[quality];
const fixed = String(fields.root ?? "").trim();
let root;
if (fixed) {
  const m = /^([A-Ga-g])(#|b|♯|♭)?$/.exec(fixed);
  if (!m) throw new Error(`root must be a note name like C, F#, Bb (got "${fixed}")`);
  root = { letter: m[1].toUpperCase(), acc: !m[2] ? 0 : m[2] === "#" || m[2] === "♯" ? 1 : -1 };
} else {
  root = rng.pick(["C", "G", "D", "A", "E", "B", "F#", "Db", "Ab", "Eb", "Bb", "F"].map((r) => ({ letter: r[0], acc: r[1] === "b" ? -1 : r[1] === "#" ? 1 : 0 })));
}
const spelled = tones.map(([deg, steps, semis]) => ({ deg, note: up(root, steps, semis) }));
// Root position, close voicing, inside the keyboard (C3 to B4); the root sits in the lower or upper octave when the top note still fits.
const top = tones[tones.length - 1][2];
const bases = [48, 60].filter((b) => b + pcOf(root) + top <= 71);
const base = rng.pick(bases) + pcOf(root);
const lit = tones.map(([, , semis]) => base + semis);
return {
  view: {
    prompt: fields.prompt ?? "",
    lit,
    style,
    qualities: pool.filter((q, i) => pool.indexOf(q) === i),
  },
  key: {
    quality,
    qualityName: NAMES[quality],
    rootName: txt(root),
    symbol: `${txt(root)}${sfx}`,
    tex: `${tex(root)}${qtex}`,
    tones: spelled.map((t) => ({ deg: t.deg, name: txt(t.note) })),
    explanation: fields.explanation ?? "",
  },
};

