// answer: { major: "A♭" | null, minor: "F" | null }; only the asked parts count, equal shares.
const a = answer && typeof answer === "object" ? answer : {};
const parts = [];
if (key.ask !== "minor") parts.push(["major", a.major === key.major]);
if (key.ask !== "major") parts.push(["minor", a.minor === key.minor]);
const score = parts.filter(([, ok]) => ok).length / parts.length;
const given = parts.some(([p]) => a[p]);
const sentence = `${key.summary}: ${key.major} major, relative minor ${key.minor} minor.`;
const bad = parts.filter(([, ok]) => !ok).map(([p]) => p);
const feedback = score === 1 ? undefined : given ? `${sentence} Check the ${bad.join(" and the ")} key.` : `Pick a key. ${sentence}`;
return { score, feedback, details: Object.fromEntries(parts) };

