// Major keys by signature: index n (0 to 7) = n sharps, then 1 to 7 flats; relative minors alongside.
const MAJ_SHARP = ["C", "G", "D", "A", "E", "B", "F♯", "C♯"], MIN_SHARP = ["A", "E", "B", "F♯", "C♯", "G♯", "D♯", "A♯"];
const MAJ_FLAT = ["F", "B♭", "E♭", "A♭", "D♭", "G♭", "C♭"], MIN_FLAT = ["D", "G", "C", "F", "B♭", "E♭", "A♭"];
const ORDER_SHARP = ["F", "C", "G", "D", "A", "E", "B"], ORDER_FLAT = ["B", "E", "A", "D", "G", "C", "F"];
// Staff positions: 0 = bottom line, 1 = first space, 2 = second line ... 8 = top line.
// Treble: F5 C5 G5 D5 A4 E5 B4 and B4 E5 A4 D5 G4 C5 F4. Bass sits two positions lower: F3 C3 G3 D3 A2 E3 B2, B2 E3 A2 D3 G2 C3 F2.
const POS = {
  treble: { sharp: [8, 5, 9, 6, 3, 7, 4], flat: [4, 7, 3, 6, 2, 5, 1] },
  bass: { sharp: [6, 3, 7, 4, 1, 5, 2], flat: [2, 5, 1, 4, 0, 3, -1] },
};
const norm = (s) => String(s).trim().replace(/#/g, "♯").replace(/(?<=.)b$/, "♭").replace(/^([a-g])/, (c) => c.toUpperCase());
const all = [...MAJ_SHARP, ...MAJ_FLAT];
let pool = (Array.isArray(fields.keys) ? fields.keys : []).map(norm);
for (const k of pool) if (!all.includes(k)) throw new Error(`keys: "${k}" is not one of ${all.join(" ")}`);
if (!pool.length) pool = all;
const major = rng.pick(pool);
const n = MAJ_SHARP.includes(major) ? MAJ_SHARP.indexOf(major) : -(MAJ_FLAT.indexOf(major) + 1);
const clefIn = String(fields.clef ?? "").trim().toLowerCase() || "treble";
if (!["treble", "bass", "both"].includes(clefIn)) throw new Error(`clef must be treble, bass or both (got "${fields.clef}")`);
const clef = clefIn === "both" ? rng.pick(["treble", "bass"]) : clefIn;
const askIn = String(fields.ask ?? "").trim().toLowerCase() || "both";
if (!["major", "minor", "both"].includes(askIn)) throw new Error(`ask must be major, minor or both (got "${fields.ask}")`);
const count = Math.abs(n);
const sharp = n > 0;
const accidentals = (sharp ? ORDER_SHARP : ORDER_FLAT).slice(0, count).map((l) => l + (sharp ? "♯" : "♭"));
const pos = (sharp ? POS[clef].sharp : POS[clef].flat).slice(0, count);
const minor = n >= 0 ? MIN_SHARP[n] : MIN_FLAT[-n - 1];
return {
  view: {
    prompt: fields.prompt ?? "",
    clef,
    sharp,
    pos,
    ask: askIn,
    askMajor: askIn !== "minor",
    askMinor: askIn !== "major",
    help: askIn === "major" ? "Pick the major key." : askIn === "minor" ? "Pick the minor key." : "Pick the major key and its relative minor.",
  },
  key: {
    n,
    major,
    minor,
    ask: askIn,
    count,
    accidentals,
    summary: count === 0 ? "No sharps or flats" : `${count} ${sharp ? (count === 1 ? "sharp" : "sharps") : count === 1 ? "flat" : "flats"} (${accidentals.join(" ")})`,
    explanation: fields.explanation ?? "",
  },
};

