// answer: { root: pitch class, quality, bass: pitch class or null for root position }
const a = answer && typeof answer === "object" ? answer : {};
if (!Number.isInteger(a.root) || !a.quality) return { score: 0, feedback: "Pick a root and a quality." };
const rootOk = ((a.root % 12) + 12) % 12 === key.root;
const qualOk = a.quality === key.quality;
const bass = Number.isInteger(a.bass) ? ((a.bass % 12) + 12) % 12 : null;
// Root position: "root pos." or the root itself as the bass.
const bassOk = !key.bassOn || bass === key.bass || (key.bass === null && bass === key.root);
const parts = key.bassOn ? 3 : 2;
const score = ((rootOk ? 1 : 0) + (qualOk ? 1 : 0) + (key.bassOn && bassOk ? 1 : 0)) / parts;
const bad = [!rootOk && "root", !qualOk && "quality", !bassOk && "bass note"].filter(Boolean);
const feedback = score === 1 ? undefined : `The chord is ${key.symbol}; check the ${bad.join(" and the ")}.`;
return { score, feedback, details: { rootOk, qualOk, bassOk } };

