// A soft piano voice: a handful of harmonics, a quick hammer attack and a two-stage decay.
// The AudioContext is created on the first gesture inside the frame (browsers require one).
const Piano = (() => {
  let ctx = null, out = null, wave = null, noise = null;
  const setup = (c, dest) => {
    const comp = c.createDynamicsCompressor();
    comp.threshold.value = -18; comp.knee.value = 14; comp.ratio.value = 3;
    comp.attack.value = 0.003; comp.release.value = 0.3;
    const g = c.createGain();
    g.gain.value = 0.7;
    g.connect(comp); comp.connect(dest);
    const amps = [0, 1, 0.45, 0.28, 0.17, 0.1, 0.06, 0.035, 0.02, 0.012];
    const w = c.createPeriodicWave(new Float32Array(amps.length), Float32Array.from(amps));
    const n = c.createBuffer(1, Math.ceil(c.sampleRate * 0.04), c.sampleRate);
    const d = n.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / d.length);
    return { out: g, wave: w, noise: n };
  };
  const get = () => {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    if (!ctx) {
      ctx = new AC();
      ({ out, wave, noise } = setup(ctx, ctx.destination));
    }
    if (ctx.state === "suspended") ctx.resume();
    return ctx;
  };
  // iOS Safari unlocks audio on touchend or pointerup, not on the pointerdown the controls use.
  for (const t of ["pointerup", "touchend", "keydown"]) window.addEventListener(t, () => get(), { passive: true });
  const voice = (c, dest, w, nz, midi, t, len, vel) => {
    const f = 440 * 2 ** ((midi - 69) / 12);
    const ring = Math.max(0.6, 2.8 - (midi - 48) * 0.045); // low notes ring longer
    const peak = 0.2 * vel;
    const env = c.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(peak, t + 0.005);
    env.gain.setTargetAtTime(peak * 0.4, t + 0.005, 0.08);
    env.gain.setTargetAtTime(0.0001, t + 0.2, ring / 4);
    const stop = t + Math.min(len ?? ring, ring) ;
    env.gain.setTargetAtTime(0.0001, stop, 0.09);
    const lp = c.createBiquadFilter();
    lp.type = "lowpass"; lp.Q.value = 0.5;
    lp.frequency.setValueAtTime(Math.min(f * 10, 15000), t);
    lp.frequency.setTargetAtTime(Math.min(f * 3.2, 8000), t + 0.01, 0.3);
    lp.connect(env); env.connect(dest);
    [[0, 1], [5, 0.55], [-4, 0.35]].forEach(([cents, a]) => {
      const o = c.createOscillator();
      o.setPeriodicWave(w); o.frequency.value = f; o.detune.value = cents;
      const g = c.createGain(); g.gain.value = a;
      o.connect(g); g.connect(lp);
      o.start(t); o.stop(stop + 0.6);
    });
    const h = c.createBufferSource(); h.buffer = nz;
    const bp = c.createBiquadFilter(); bp.type = "bandpass"; bp.frequency.value = Math.min(f * 4, 6000); bp.Q.value = 1.2;
    const hg = c.createGain(); hg.gain.value = 0.05 * vel;
    h.connect(bp); bp.connect(hg); hg.connect(dest);
    h.start(t);
  };
  return {
    /** notes: [{ m: midi, at: seconds from now, len?: seconds, vel?: 0..1 }]. Returns the total length. */
    play(notes) {
      const c = get();
      if (!c) return 0;
      const t0 = c.currentTime + 0.04;
      let end = 0;
      for (const n of notes) {
        voice(c, out, wave, noise, n.m, t0 + (n.at ?? 0), n.len, n.vel ?? 0.8);
        end = Math.max(end, (n.at ?? 0) + (n.len ?? 1.2));
      }
      return end;
    },
    /** Renders notes offline (for checking the sound without speakers). */
    async render(notes, seconds = 3) {
      const c = new OfflineAudioContext(1, Math.ceil(44100 * seconds), 44100);
      const s = setup(c, c.destination);
      for (const n of notes) voice(c, s.out, s.wave, s.noise, n.m, n.at ?? 0, n.len, n.vel ?? 0.8);
      return c.startRendering();
    },
  };
})();

const PLAY_ICON = `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13a1 1 0 0 0 1.5.86l10.5-6.5a1 1 0 0 0 0-1.72L9.5 4.64A1 1 0 0 0 8 5.5Z" fill="currentColor"/></svg>`;

// Piano keyboard drawn one octave (C to B) per SVG, so narrow screens can stack octaves.
// keyboard(host, { lo, octaves, wrap, labels, onPress }) returns { el(midi), all(), set(midi, cls, on), label(midi, text) }.
function keyboard(host, { lo = 48, octaves = 2, wrap = true, labels = "c", onPress = null } = {}) {
  const W = 24, H = 104, BW = 16, BH = 66, R = 3;
  const WHITE = [0, 2, 4, 5, 7, 9, 11];
  const BLACK = { 1: [1, -0.12], 3: [2, 0.12], 6: [4, -0.16], 8: [5, 0], 10: [6, 0.16] }; // pc -> [boundary, offset]
  const LETTER = { 0: "C", 2: "D", 4: "E", 5: "F", 7: "G", 9: "A", 11: "B" };
  const SPOKEN = ["C", "C♯", "D", "E♭", "E", "F", "F♯", "G", "A♭", "A", "B♭", "B"];
  const aria = (m) => `role="button" aria-label="${SPOKEN[m % 12]}${Math.floor(m / 12) - 1}"`;
  const whitePath = (x) => `M${x + 0.5} 0.5H${x + W - 0.5}V${H - R - 0.5}Q${x + W - 0.5} ${H - 0.5} ${x + W - R - 0.5} ${H - 0.5}H${x + R + 0.5}Q${x + 0.5} ${H - 0.5} ${x + 0.5} ${H - R - 0.5}Z`;
  host.classList.add("kb");
  if (!wrap) host.classList.add("kb-nowrap");
  let html = "";
  for (let k = 0; k < octaves; k++) {
    const base = lo + 12 * k;
    let s = `<svg class="kb-oct" viewBox="0 0 ${7 * W} ${H}" role="group" aria-label="Octave ${Math.floor(base / 12) - 1}">`;
    WHITE.forEach((pc, i) => {
      const m = base + pc, x = i * W;
      const text = labels === "all" ? LETTER[pc] : labels === "c" && pc === 0 ? `C${Math.floor(m / 12) - 1}` : "";
      s += `<g class="key white" data-m="${m}" ${aria(m)}><path d="${whitePath(x)}"/><text x="${x + W / 2}" y="${H - 9}" class="kl">${text}</text></g>`;
    });
    for (const [pc, [b, off]] of Object.entries(BLACK)) {
      const m = base + Number(pc), x = (b + off) * W - BW / 2;
      s += `<g class="key black" data-m="${m}" ${aria(m)}><path d="M${x} 0H${x + BW}V${BH - 2}Q${x + BW} ${BH} ${x + BW - 2} ${BH}H${x + 2}Q${x} ${BH} ${x} ${BH - 2}Z"/><text x="${x + BW / 2}" y="${BH - 7}" class="kl"></text></g>`;
    }
    html += s + "</svg>";
  }
  host.innerHTML = html;
  const map = new Map([...host.querySelectorAll(".key")].map((g) => [Number(g.dataset.m), g]));
  if (onPress) {
    host.addEventListener("pointerdown", (e) => {
      const g = e.target.closest?.(".key");
      if (!g || e.button > 0) return;
      e.preventDefault();
      g.classList.add("down");
      setTimeout(() => g.classList.remove("down"), 160);
      onPress(Number(g.dataset.m));
    });
  }
  return {
    el: (m) => map.get(m),
    all: () => [...map.keys()],
    set(m, cls, on = true) { map.get(m)?.classList.toggle(cls, on); },
    clear(cls) { for (const g of map.values()) g.classList.remove(cls); },
    label(m, text) { const t = map.get(m)?.querySelector("text"); if (t) t.textContent = text; },
  };
}

const { view } = etude;
const LO = 48; // C3
const CIRCLE = [[0, "C"], [7, "G"], [2, "D"], [9, "A"], [4, "E"], [11, "B"], [6, "F♯"], [1, "D♭"], [8, "A♭"], [3, "E♭"], [10, "B♭"], [5, "F"]];
const CHROMA = ["C", "D♭", "D", "E♭", "E", "F", "F♯", "G", "A♭", "A", "B♭", "B"].map((n, i) => [i, n]);
const QL = { maj: "maj", min: "m", dim: "dim", aug: "aug", sus2: "sus2", sus4: "sus4", maj7: "maj7", "7": "7", m7: "m7", m7b5: "m7♭5", dim7: "dim7" };
const prev = etude.answer && typeof etude.answer === "object" ? etude.answer : {};
const pick = { root: prev.root ?? null, quality: prev.quality ?? null, bass: view.bassOn ? (prev.bass ?? null) : null };

const kb = keyboard(etude.$(".nc-kb"), { lo: LO, octaves: 2, labels: "c" });
view.lit.forEach((m) => kb.set(m, "sel"));
const notes = view.lit.map((m, i) => ({ m, at: i * 0.07, len: 1.8, vel: 0.65 }));
const play = etude.$(".nc-play");
play.querySelector(".ic").innerHTML = PLAY_ICON;
play.addEventListener("click", () => Piano.play(notes));

const rows = { root: etude.$(".nc-root"), quality: etude.$(".nc-quality"), bass: etude.$(".nc-bass") };
const ready = () => etude.setReady(etude.mode === "answer" && pick.root != null && pick.quality != null);
const paint = () => {
  for (const [k, host] of Object.entries(rows).filter(([, h]) => h))
    host.querySelectorAll("button").forEach((b) => b.setAttribute("aria-pressed", String(String(pick[k]) === b.dataset.v)));
  ready();
};
const fill = (k, items) => {
  rows[k].innerHTML = items.map(([v, label]) => `<button type="button" class="nc-btn" data-v="${v}">${label}</button>`).join("");
  rows[k].addEventListener("click", (e) => {
    const b = e.target.closest("button");
    if (!b || etude.mode !== "answer") return;
    pick[k] = b.dataset.v === "null" ? null : k === "quality" ? b.dataset.v : Number(b.dataset.v);
    paint();
  });
};
fill("root", CIRCLE);
fill("quality", view.qualities.map((q) => [q, QL[q]]));
if (view.bassOn) fill("bass", [["null", "root pos."], ...CHROMA]);
paint();
etude.getAnswer(() => ({ root: pick.root, quality: pick.quality, bass: pick.bass }));

etude.onResult(({ key }) => {
  etude.$$(".nc-btn").forEach((b) => (b.disabled = true));
  const mark = (k, right) => rows[k].querySelectorAll("button").forEach((b) => {
    if (b.dataset.v === String(right)) b.classList.add("is-correct");
    else if (b.dataset.v === String(pick[k])) b.classList.add("is-wrong");
  });
  mark("root", key.root);
  mark("quality", key.quality);
  if (key.bassOn) mark("bass", key.bass);
  etude.$(".nc-sym").innerHTML = etude.mdInline(`$${key.tex}$`);
  etude.$(".nc-tones").innerHTML = `<div class="cd-row">${key.tones.map((t) => `<div class="cd-tone"><span class="deg">${t.deg}</span><span class="nm">${etude.mdInline(`$${t.tex}$`)}</span></div>`).join("")}</div>`;
  const hear = etude.$(".nc-hear");
  hear.querySelector(".ic").innerHTML = PLAY_ICON;
  hear.addEventListener("click", () => Piano.play(notes));
});

grader.code:
const steps = key.steps;
const given = Array.isArray(answer) ? answer : [];
const SP = ["C", "C♯", "D", "E♭", "E", "F", "F♯", "G", "A♭", "A", "B♭", "B"];
const scores = [], bad = [];
steps.forEach((s, i) => {
  const keys = (Array.isArray(given[i]) ? given[i] : []).filter((m) => Number.isInteger(m));
  const pcs = [...new Set(keys.map((m) => ((m % 12) + 12) % 12))];
  const want = new Set(s.pcs);
  const hit = pcs.filter((p) => want.has(p));
  const extra = pcs.filter((p) => !want.has(p));
  const missing = s.pcs.filter((p) => !pcs.includes(p));
  // Each chord tone found earns its share; each wrong pitch class takes one share away.
  scores.push(Math.max(0, (hit.length - extra.length) / s.pcs.length));
  if (!missing.length && !extra.length) return;
  const nm = (p) => s.tones.find((t) => t.pc === p)?.name;
  const parts = [];
  if (!keys.length) parts.push("no keys pressed");
  else {
    if (missing.length) parts.push(`missing ${missing.map(nm).join(", ")}`);
    if (extra.length) parts.push(`${extra.map((p) => SP[p]).join(", ")} ${extra.length === 1 ? "isn't" : "aren't"} in the chord`);
  }
  bad.push(`Step ${i + 1} (${s.numeral}): ${parts.join("; ")}.`);
});
const score = scores.reduce((a, b) => a + b, 0) / steps.length;
if (!given.some((g) => Array.isArray(g) && g.length)) return { score: 0, feedback: "No keys pressed." };
return { score, feedback: bad.length ? bad.join(" ") : undefined, details: { steps: scores } };

types.prepare:
const LET = "CDEFGAB", PCS = [0, 2, 4, 5, 7, 9, 11];
const pcOf = (n) => (((PCS[LET.indexOf(n.letter)] + n.acc) % 12) + 12) % 12;
const up = (n, steps, semis) => {
  const li = LET.indexOf(n.letter) + steps;
  const t = { letter: LET[li % 7], acc: 0 };
  t.acc = ((pcOf(n) + semis - PCS[li % 7] + 18) % 12) - 6;
  return t;
};
const ACC = { "-2": "𝄫", "-1": "♭", 0: "", 1: "♯", 2: "𝄪" };
const TEX = { "-2": "{\\flat\\flat}", "-1": "{\\flat}", 0: "", 1: "{\\sharp}", 2: "{\\sharp\\sharp}" };
const txt = (n) => `${n.letter}${ACC[n.acc]}`;
const tex = (n) => `\\mathrm{${n.letter}}${TEX[n.acc]}`;
const parse = (s) => { const m = /^([A-Ga-g])(#|b|♯|♭)?$/.exec(s); return m && { letter: m[1].toUpperCase(), acc: !m[2] ? 0 : m[2] === "#" || m[2] === "♯" ? 1 : -1 }; };

const mode = String(fields.mode ?? "").trim().toLowerCase() || "major";
if (mode !== "major" && mode !== "minor") throw new Error(`mode must be major or minor (got "${fields.mode}")`);
const minor = mode === "minor";
const ROMAN = ["i", "ii", "iii", "iv", "v", "vi", "vii"];
// "ii7-V7-Imaj7", with - or – between the numerals.
const src = String(fields.progression ?? "").trim() || "I-IV-V-I";
const parsed = src.split(/\s*[-–—]\s*/).map((tok) => {
  const m = /^(vii|vi|iv|v|iii|ii|i)(7|maj7)?$/i.exec(tok);
  if (!m) throw new Error(`bad numeral "${tok}" in progression "${src}" (use i to vii, optionally with 7 or maj7)`);
  return { d: ROMAN.indexOf(m[1].toLowerCase()), sev: !!m[2] };
});

const fixed = String(fields.key ?? "").trim();
const tonic = parse(fixed || rng.pick(minor ? ["A", "E", "B", "F#", "C#", "G#", "D#", "Bb", "F", "C", "G", "D"] : ["C", "G", "D", "A", "E", "B", "F#", "Db", "Ab", "Eb", "Bb", "F"]));
if (!tonic) throw new Error(`key must be a note name like C, F#, Bb (got "${fixed}")`);
// The scale is spelled one letter per degree; minor takes the harmonic 7th for V and vii°.
const NAT = minor ? [0, 2, 3, 5, 7, 8, 10] : [0, 2, 4, 5, 7, 9, 11];
const scale = (s) => s.map((semis, i) => up(tonic, i, semis));
const natural = scale(NAT), harmonic = scale(minor ? [0, 2, 3, 5, 7, 8, 11] : NAT);
if ([...natural, ...harmonic].some((n) => Math.abs(n.acc) > 2)) throw new Error(`${fixed} ${mode} needs more than double accidentals`);

// intervals above the root -> [symbol suffix, numeral suffix (text), numeral suffix (tex), upper case]
const QUAL = {
  "4,7": ["", "", "", true], "3,7": ["m", "", "", false], "3,6": ["dim", "°", "^{\\circ}", false], "4,8": ["aug", "+", "^{+}", true],
  "4,7,11": ["maj7", "maj7", "\\mathrm{maj7}", true], "4,7,10": ["7", "7", "^{7}", true], "3,7,10": ["m7", "7", "^{7}", false],
  "3,6,10": ["m7♭5", "ø7", "^{\\varnothing 7}", false], "3,6,9": ["dim7", "°7", "^{\\circ 7}", false],
};
const DEG = { 3: "♭3", 4: "3", 6: "♭5", 7: "5", 8: "♯5", 9: "𝄫7", 10: "♭7", 11: "7" };
const steps = parsed.map(({ d, sev }) => {
  const harm = minor && (d === 4 || d === 6);
  const sc = harm ? harmonic : natural;
  const notes = [0, 2, 4, ...(sev ? [6] : [])].map((k) => sc[(d + k) % 7]);
  const iv = notes.slice(1).map((n) => (pcOf(n) - pcOf(notes[0]) + 12) % 12).join(",");
  const q = QUAL[iv];
  if (!q) throw new Error(`unexpected chord ${iv}`);
  const roman = q[3] ? ROMAN[d].toUpperCase() : ROMAN[d];
  return {
    numeral: roman + q[1], numTex: `\\mathrm{${roman}}${q[2]}`,
    symbol: `${txt(notes[0])}${q[0]}`, pcs: notes.map(pcOf), harm,
    tones: notes.map((n, i) => ({ deg: i ? DEG[(pcOf(n) - pcOf(notes[0]) + 12) % 12] : "1", name: txt(n), tex: tex(n), pc: pcOf(n) })),
  };
});
const keyName = `${txt(tonic)} ${mode}`, keyTex = `${tex(tonic)}\\ \\mathrm{${mode}}`;
const shown = steps.map((s) => s.numeral).join("–");
return {
  view: {
    prompt: fields.prompt ?? "",
    q: `Play this progression in $${keyTex}$`,
    steps: steps.map((s) => ({ numeral: s.numeral, tex: s.numTex })),
    help: "Build each chord, then tap Next. Any voicing or inversion counts.",
    how: `The grader compared pitch classes step by step, so any octave, voicing or inversion of the right notes counts. Each chord is stacked in thirds from the ${keyName} scale${minor ? " (natural minor, with the harmonic-minor V and vii°)" : ""}, so its spelling follows the key.`,
  },
  key: {
    steps,
    result: `${shown} in ${keyName} = ${steps.map((s) => s.symbol).join(" – ")}`,
    explanation: fields.explanation ?? "",
  },
};

