// An example answer for watch mode: each chord in root position, stacked above C3.
return key.steps.map((s) => {
  const out = [];
  for (const pc of s.pcs) {
    let m = 48 + pc;
    while (out.length && m <= out[out.length - 1]) m += 12;
    out.push(m);
  }
  return out;
});

