/* Piano keyboard (shared by the music types). Keys keep piano colors in every theme: it's an object, not a surface. */
/* Octaves sit side by side as one keyboard; on phones a two-octave keyboard stacks so keys stay tappable. */
.kb { display: flex; flex-wrap: nowrap; justify-content: center; gap: 0; width: 100%; }
.kb-oct { flex: 1 1 0; min-width: 0; max-width: 20rem; height: auto; display: block; touch-action: manipulation; user-select: none; -webkit-user-select: none; }
@media (max-width: 520px) { .kb:not(.kb-nowrap) { flex-wrap: wrap; gap: 0.6rem; } .kb:not(.kb-nowrap) .kb-oct { flex-basis: 100%; max-width: 22rem; } }
.key path { stroke: rgba(0, 0, 0, 0.5); stroke-width: 1; transition: fill 0.12s; cursor: pointer; }
.kb.static .key path { cursor: default; }
.key.white path { fill: #f4f1ea; }
.key.black path { fill: #252321; stroke: #0e0d0c; }
