.pg-step.done::after { content: ""; position: absolute; top: 5px; right: 5px; width: 6px; height: 6px; border-radius: 50%; background: var(--highlight); }
.pg-step.cur { border-color: var(--highlight); background: color-mix(in oklab, var(--highlight) 18%, transparent); box-shadow: 0 0 0 1px var(--highlight); }
.pg-step:focus-visible { outline: none; box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring) 35%, transparent); }
.pg-back, .pg-next { min-width: 64px; }
.pg-next { border-color: color-mix(in oklab, var(--highlight) 60%, var(--border)); }
.pg-back[disabled], .pg-next[disabled] { opacity: 0.4; }
.key.white.prev path { fill: color-mix(in oklab, var(--highlight) 22%, #f4f1ea); }
.key.black.prev path { fill: color-mix(in oklab, var(--highlight) 30%, #252321); }
.pg-rows { display: flex; flex-direction: column; gap: 0.4rem; }
