.pg-row.ok { border-color: color-mix(in oklab, var(--success) 55%, var(--border)); background: color-mix(in oklab, var(--success) 10%, transparent); }
.pg-row.no { border-color: color-mix(in oklab, var(--danger) 60%, var(--border)); background: color-mix(in oklab, var(--danger) 10%, transparent); }
.pg-row .mk { font-weight: 700; width: 1.2rem; text-align: center; }
.pg-row.ok .mk { color: var(--success); }
.pg-row.no .mk { color: var(--danger); }
.pg-row .sym { font-weight: 600; }
.pg-row .tn { color: var(--muted-foreground); font-size: 0.9rem; }
.pg-row .fb { flex-basis: 100%; font-size: 0.82rem; color: var(--muted-foreground); }

