// A soft piano voice: a handful of harmonics, a quick hammer attack and a two-stage decay.
// The AudioContext is created on the first gesture inside the frame (browsers require one).
const Piano = (() => {
  let ctx = null, out = null, wave = null, noise = null;
  const setup = (c, dest) => {
    const comp = c.createDynamicsCompressor();
    comp.threshold.value = -18; comp.knee.value = 14; comp.ratio.value = 3;
    comp.attack.value = 0.003; comp.release.value = 0.3;
    const g = c.createGain();
    g.gain.value = 0.7;
    g.connect(comp); comp.connect(dest);
    const amps = [0, 1, 0.45, 0.28, 0.17, 0.1, 0.06, 0.035, 0.02, 0.012];
    const w = c.createPeriodicWave(new Float32Array(amps.length), Float32Array.from(amps));
    const n = c.createBuffer(1, Math.ceil(c.sampleRate * 0.04), c.sampleRate);
    const d = n.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / d.length);
    return { out: g, wave: w, noise: n };
  };
  const get = () => {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    if (!ctx) {
      ctx = new AC();
      ({ out, wave, noise } = setup(ctx, ctx.destination));
    }
    if (ctx.state === "suspended") ctx.resume();
    return ctx;
  };
  // iOS Safari unlocks audio on touchend or pointerup, not on the pointerdown the controls use.
  for (const t of ["pointerup", "touchend", "keydown"]) window.addEventListener(t, () => get(), { passive: true });
  const voice = (c, dest, w, nz, midi, t, len, vel) => {
    const f = 440 * 2 ** ((midi - 69) / 12);
    const ring = Math.max(0.6, 2.8 - (midi - 48) * 0.045); // low notes ring longer
    const peak = 0.2 * vel;
    const env = c.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(peak, t + 0.005);
    env.gain.setTargetAtTime(peak * 0.4, t + 0.005, 0.08);
    env.gain.setTargetAtTime(0.0001, t + 0.2, ring / 4);
    const stop = t + Math.min(len ?? ring, ring) ;
    env.gain.setTargetAtTime(0.0001, stop, 0.09);
    const lp = c.createBiquadFilter();
    lp.type = "lowpass"; lp.Q.value = 0.5;
    lp.frequency.setValueAtTime(Math.min(f * 10, 15000), t);
    lp.frequency.setTargetAtTime(Math.min(f * 3.2, 8000), t + 0.01, 0.3);
    lp.connect(env); env.connect(dest);
    [[0, 1], [5, 0.55], [-4, 0.35]].forEach(([cents, a]) => {
      const o = c.createOscillator();
      o.setPeriodicWave(w); o.frequency.value = f; o.detune.value = cents;
      const g = c.createGain(); g.gain.value = a;
      o.connect(g); g.connect(lp);
      o.start(t); o.stop(stop + 0.6);
    });
    const h = c.createBufferSource(); h.buffer = nz;
    const bp = c.createBiquadFilter(); bp.type = "bandpass"; bp.frequency.value = Math.min(f * 4, 6000); bp.Q.value = 1.2;
    const hg = c.createGain(); hg.gain.value = 0.05 * vel;
    h.connect(bp); bp.connect(hg); hg.connect(dest);
    h.start(t);
  };
  return {
    /** notes: [{ m: midi, at: seconds from now, len?: seconds, vel?: 0..1 }]. Returns the total length. */
    play(notes) {
      const c = get();
      if (!c) return 0;
      const t0 = c.currentTime + 0.04;
      let end = 0;
      for (const n of notes) {
        voice(c, out, wave, noise, n.m, t0 + (n.at ?? 0), n.len, n.vel ?? 0.8);
        end = Math.max(end, (n.at ?? 0) + (n.len ?? 1.2));
      }
      return end;
    },
    /** Renders notes offline (for checking the sound without speakers). */
    async render(notes, seconds = 3) {
      const c = new OfflineAudioContext(1, Math.ceil(44100 * seconds), 44100);
      const s = setup(c, c.destination);
      for (const n of notes) voice(c, s.out, s.wave, s.noise, n.m, n.at ?? 0, n.len, n.vel ?? 0.8);
      return c.startRendering();
    },
  };
})();

const PLAY_ICON = `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13a1 1 0 0 0 1.5.86l10.5-6.5a1 1 0 0 0 0-1.72L9.5 4.64A1 1 0 0 0 8 5.5Z" fill="currentColor"/></svg>`;

// Piano keyboard drawn one octave (C to B) per SVG, so narrow screens can stack octaves.
// keyboard(host, { lo, octaves, wrap, labels, onPress }) returns { el(midi), all(), set(midi, cls, on), label(midi, text) }.
function keyboard(host, { lo = 48, octaves = 2, wrap = true, labels = "c", onPress = null } = {}) {
  const W = 24, H = 104, BW = 16, BH = 66, R = 3;
  const WHITE = [0, 2, 4, 5, 7, 9, 11];
  const BLACK = { 1: [1, -0.12], 3: [2, 0.12], 6: [4, -0.16], 8: [5, 0], 10: [6, 0.16] }; // pc -> [boundary, offset]
  const LETTER = { 0: "C", 2: "D", 4: "E", 5: "F", 7: "G", 9: "A", 11: "B" };
  const SPOKEN = ["C", "C♯", "D", "E♭", "E", "F", "F♯", "G", "A♭", "A", "B♭", "B"];
  const aria = (m) => `role="button" aria-label="${SPOKEN[m % 12]}${Math.floor(m / 12) - 1}"`;
  const whitePath = (x) => `M${x + 0.5} 0.5H${x + W - 0.5}V${H - R - 0.5}Q${x + W - 0.5} ${H - 0.5} ${x + W - R - 0.5} ${H - 0.5}H${x + R + 0.5}Q${x + 0.5} ${H - 0.5} ${x + 0.5} ${H - R - 0.5}Z`;
  host.classList.add("kb");
  if (!wrap) host.classList.add("kb-nowrap");
  let html = "";
  for (let k = 0; k < octaves; k++) {
    const base = lo + 12 * k;
    let s = `<svg class="kb-oct" viewBox="0 0 ${7 * W} ${H}" role="group" aria-label="Octave ${Math.floor(base / 12) - 1}">`;
    WHITE.forEach((pc, i) => {
      const m = base + pc, x = i * W;
      const text = labels === "all" ? LETTER[pc] : labels === "c" && pc === 0 ? `C${Math.floor(m / 12) - 1}` : "";
      s += `<g class="key white" data-m="${m}" ${aria(m)}><path d="${whitePath(x)}"/><text x="${x + W / 2}" y="${H - 9}" class="kl">${text}</text></g>`;
    });
    for (const [pc, [b, off]] of Object.entries(BLACK)) {
      const m = base + Number(pc), x = (b + off) * W - BW / 2;
      s += `<g class="key black" data-m="${m}" ${aria(m)}><path d="M${x} 0H${x + BW}V${BH - 2}Q${x + BW} ${BH} ${x + BW - 2} ${BH}H${x + 2}Q${x} ${BH} ${x} ${BH - 2}Z"/><text x="${x + BW / 2}" y="${BH - 7}" class="kl"></text></g>`;
    }
    html += s + "</svg>";
  }
  host.innerHTML = html;
  const map = new Map([...host.querySelectorAll(".key")].map((g) => [Number(g.dataset.m), g]));
  if (onPress) {
    host.addEventListener("pointerdown", (e) => {
      const g = e.target.closest?.(".key");
      if (!g || e.button > 0) return;
      e.preventDefault();
      g.classList.add("down");
      setTimeout(() => g.classList.remove("down"), 160);
      onPress(Number(g.dataset.m));
    });
  }
  return {
    el: (m) => map.get(m),
    all: () => [...map.keys()],
    set(m, cls, on = true) { map.get(m)?.classList.toggle(cls, on); },
    clear(cls) { for (const g of map.values()) g.classList.remove(cls); },
    label(m, text) { const t = map.get(m)?.querySelector("text"); if (t) t.textContent = text; },
  };
}

// Spelled note names: { letter: "E", acc: -1, oct: 4 } -> "E♭4", or KaTeX "\mathrm{E}\flat_{4}".
const ACC = { "-2": "𝄫", "-1": "♭", 0: "", 1: "♯", 2: "𝄪" };
const ACC_TEX = { "-2": "{\\flat\\flat}", "-1": "{\\flat}", 0: "", 1: "{\\sharp}", 2: "{\\sharp\\sharp}" };
const noteText = (n) => `${n.letter}${ACC[n.acc]}${n.oct ?? ""}`;
const noteTex = (n) => `\\mathrm{${n.letter}}${ACC_TEX[n.acc]}${n.oct != null ? `_{${n.oct}}` : ""}`;

const { view } = etude;
const LO = 48; // C3
const SP = ["C", "C♯", "D", "E♭", "E", "F", "F♯", "G", "A♭", "A", "B♭", "B"];
etude.$(".kc-q").innerHTML = etude.mdInline(view.q);
const N = view.steps.length;
const saved = Array.isArray(etude.answer) ? etude.answer : [];
const sels = view.steps.map((_, i) => new Set(Array.isArray(saved[i]) ? saved[i] : []));
let cur = 0;
const stepsEl = etude.$(".pg-steps");
const back = etude.$(".pg-back"), next = etude.$(".pg-next");
const count = etude.$(".cd-count");
stepsEl.innerHTML = view.steps.map((s, i) => `<button type="button" class="pg-step" data-i="${i}" aria-label="Step ${i + 1}, ${s.numeral}">${etude.mdInline(`$${s.tex}$`)}</button>`).join("");
const paint = () => {
  const sel = sels[cur], prev = cur ? sels[cur - 1] : new Set();
  kb.all().forEach((m) => { kb.set(m, "sel", sel.has(m)); kb.set(m, "prev", prev.has(m) && !sel.has(m)); });
  stepsEl.querySelectorAll(".pg-step").forEach((b, i) => {
    b.classList.toggle("cur", i === cur);
    b.classList.toggle("done", sels[i].size > 0);
    b.setAttribute("aria-current", i === cur ? "step" : "false");
  });
  back.disabled = cur === 0;
  next.disabled = cur === N - 1;
  count.textContent = sel.size ? `${sel.size} key${sel.size === 1 ? "" : "s"}.` : "";
  etude.setReady(etude.mode === "answer" && sels.every((s) => s.size > 0));
};
const go = (i) => { cur = Math.max(0, Math.min(N - 1, i)); paint(); };
const kb = keyboard(etude.$(".cd-kb"), {
  lo: LO, octaves: 2, labels: "c",
  onPress: (m) => {
    if (etude.mode !== "answer") return;
    const sel = sels[cur];
    if (sel.has(m)) sel.delete(m);
    else { sel.add(m); Piano.play([{ m, len: 0.9 }]); }
    paint();
  },
});
const chordNotes = (ms, at = 0) => [...ms].sort((a, b) => a - b).map((m, i) => ({ m, at: at + i * 0.07, len: 1.6, vel: 0.65 }));
const playSel = etude.$(".cd-play");
playSel.querySelector(".ic").innerHTML = PLAY_ICON;
playSel.addEventListener("click", () => sels[cur].size && Piano.play(chordNotes(sels[cur])));
etude.$(".cd-clear").addEventListener("click", () => { sels[cur].clear(); paint(); });
back.addEventListener("click", () => go(cur - 1));
next.addEventListener("click", () => go(cur + 1));
stepsEl.addEventListener("click", (e) => { const b = e.target.closest(".pg-step"); if (b && etude.mode === "answer") go(Number(b.dataset.i)); });
paint();
etude.getAnswer(() => sels.map((s) => [...s].sort((a, b) => a - b)));

// Close voicing: root first, each tone placed in the next octave position above it.
const voicing = (pcs) => pcs.map((pc) => LO + pcs[0] + ((pc - pcs[0] + 12) % 12));
etude.onResult(({ key, answer }) => {
  const given = Array.isArray(answer) ? answer : [];
  for (const sel of sels) sel.clear();
  etude.$(".pg-steps").remove();
  etude.$(".cd-kb").remove();
  etude.$(".kc-res").textContent = key.result;
  etude.$(".pg-rows").innerHTML = key.steps.map((s, i) => {
    const pcs = [...new Set((Array.isArray(given[i]) ? given[i] : []).map((m) => ((m % 12) + 12) % 12))];
    const ok = pcs.length === s.pcs.length && s.pcs.every((p) => pcs.includes(p));
    const played = pcs.length ? pcs.map((p) => s.tones.find((t) => t.pc === p)?.name ?? SP[p]).join(" ") : "nothing";
    return `<div class="pg-row ${ok ? "ok" : "no"}"><span class="mk" aria-label="${ok ? "right" : "wrong"}">${ok ? "✓" : "✗"}</span><span>${etude.mdInline(`$${view.steps[i].tex}$`)}</span><span class="sym">${s.symbol}</span><span class="tn">${s.tones.map((t) => t.name).join(" ")}</span>${ok ? "" : `<span class="fb">You played: ${played}</span>`}</div>`;
  }).join("");
  const ans = etude.$(".cd-ans");
  ans.querySelector(".ic").innerHTML = PLAY_ICON;
  ans.addEventListener("click", () => Piano.play(key.steps.flatMap((s, i) => chordNotes(voicing(s.pcs), i * 1.2))));
});

grader.code:
const got = Array.isArray(answer) ? answer.filter((m) => Number.isInteger(m)) : [];
if (!got.length) return { score: 0, feedback: "No notes played." };
const want = key.seq, n = want.length;
const correct = want.map((t, i) => i < got.length && ((got[i] % 12) + 12) % 12 === t.pc);
const right = correct.filter(Boolean).length;
const extra = Math.max(0, got.length - n);
// Each correct position earns 1/n; each note beyond the end takes one share away.
const score = Math.min(1, Math.max(0, (right - extra) / n));
const parts = [];
const bad = correct.indexOf(false);
if (bad >= 0) parts.push(`Note ${bad + 1} should be ${want[bad].name}${bad >= got.length ? " (not played)" : ""}.`);
if (got.length < n) parts.push(`${n - got.length} note${n - got.length === 1 ? "" : "s"} missing.`);
if (extra) parts.push(`${extra} extra note${extra === 1 ? "" : "s"} after the end.`);
return { score, feedback: parts.length ? parts.join(" ") : undefined, details: { correct, extra } };

types.prepare:
const LET = "CDEFGAB", PCS = [0, 2, 4, 5, 7, 9, 11];
const pcOf = (n) => (((PCS[LET.indexOf(n.letter)] + n.acc) % 12) + 12) % 12;
const up = (n, steps, semis) => {
  const li = LET.indexOf(n.letter) + steps;
  const t = { letter: LET[li % 7], acc: 0 };
  t.acc = ((pcOf(n) + semis - PCS[li % 7] + 18) % 12) - 6;
  return t;
};
const ACC = { "-2": "𝄫", "-1": "♭", 0: "", 1: "♯", 2: "𝄪" };
const TEX = { "-2": "{\\flat\\flat}", "-1": "{\\flat}", 0: "", 1: "{\\sharp}", 2: "{\\sharp\\sharp}" };
const txt = (n) => `${n.letter}${ACC[n.acc]}`;
const tex = (n) => `\\mathrm{${n.letter}}${TEX[n.acc]}`;

// Tonic to the upper tonic, as [degree label, letter steps, semitones].
const T = (d, s, m) => [d, s, m];
const MAJOR = [T("1", 0, 0), T("2", 1, 2), T("3", 2, 4), T("4", 3, 5), T("5", 4, 7), T("6", 5, 9), T("7", 6, 11), T("8", 7, 12)];
const NAT = [T("1", 0, 0), T("2", 1, 2), T("♭3", 2, 3), T("4", 3, 5), T("5", 4, 7), T("♭6", 5, 8), T("♭7", 6, 10), T("8", 7, 12)];
const S = {
  major: ["major", MAJOR, false],
  "natural-minor": ["natural minor", NAT, false],
  "harmonic-minor": ["harmonic minor", [...NAT.slice(0, 6), T("7", 6, 11), NAT[7]], false],
  "melodic-minor-asc": ["melodic minor, ascending", [...NAT.slice(0, 5), T("6", 5, 9), T("7", 6, 11), NAT[7]], false],
  "melodic-minor-desc": ["melodic minor, descending", NAT, true],
  "major-pentatonic": ["major pentatonic", [T("1", 0, 0), T("2", 1, 2), T("3", 2, 4), T("5", 4, 7), T("6", 5, 9), T("8", 7, 12)], false],
  "minor-pentatonic": ["minor pentatonic", [T("1", 0, 0), T("♭3", 2, 3), T("4", 3, 5), T("5", 4, 7), T("♭7", 6, 10), T("8", 7, 12)], false],
  "major-blues": ["major blues", [T("1", 0, 0), T("2", 1, 2), T("♭3", 2, 3), T("3", 2, 4), T("5", 4, 7), T("6", 5, 9), T("8", 7, 12)], false],
  "minor-blues": ["minor blues", [T("1", 0, 0), T("♭3", 2, 3), T("4", 3, 5), T("♭5", 4, 6), T("5", 4, 7), T("♭7", 6, 10), T("8", 7, 12)], false],
};
let pool = (Array.isArray(fields.scales) ? fields.scales : []).filter((s) => S[s]);
if (!pool.length) pool = Object.keys(S);
const id = rng.pick(pool);
const [sname, tones, desc] = S[id];
const m = /^([A-Ga-g])(#|b|♯|♭)?$/.exec(String(fields.root ?? "").trim());
if (!m) throw new Error(`root must be a note name like C, F#, Bb (got "${fields.root}")`);
const root = { letter: m[1].toUpperCase(), acc: !m[2] ? 0 : m[2] === "#" || m[2] === "♯" ? 1 : -1 };
// Playback MIDI sits in 48..71 (tonic in C3-B3, upper tonic an octave above); descending reverses the order.
const seq = tones.map(([deg, steps, semis]) => {
  const n = up(root, steps, semis);
  return { deg, name: txt(n), tex: tex(n), pc: (pcOf(root) + semis) % 12, m: 48 + pcOf(root) + semis };
});
if (desc) seq.reverse();
const count = seq.length;
return {
  view: {
    prompt: fields.prompt ?? "",
    tex: tex(root),
    scale: sname,
    name: `${txt(root)} ${sname}`,
    count,
    help: `Tap ${count} notes in order, ${desc ? "from the upper tonic down to the tonic" : "from the tonic up to the tonic an octave higher"}.`,
    how: `The grader compared the notes in order by pitch class, so any starting octave and any octave jumps count. The scale has ${count} notes, tonic to tonic.`,
  },
  key: { seq, desc, explanation: fields.explanation ?? "" },
};

template.css:
.sc-eyebrow { font-size: 0.72rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--highlight); margin-bottom: -0.5rem; }
.sc-how { font-size: 0.85rem; color: var(--muted-foreground); border-top: 1px solid var(--border); padding-top: 0.75rem; margin: 0.25rem 0 0; }

/* Piano keyboard (shared by the music types). Keys keep piano colors in every theme: it's an object, not a surface. */
/* Octaves sit side by side as one keyboard; on phones a two-octave keyboard stacks so keys stay tappable. */
.kb { display: flex; flex-wrap: nowrap; justify-content: center; gap: 0; width: 100%; }
.kb-oct { flex: 1 1 0; min-width: 0; max-width: 20rem; height: auto; display: block; touch-action: manipulation; user-select: none; -webkit-user-select: none; }
@media (max-width: 520px) { .kb:not(.kb-nowrap) { flex-wrap: wrap; gap: 0.6rem; } .kb:not(.kb-nowrap) .kb-oct { flex-basis: 100%; max-width: 22rem; } }
.key path { stroke: rgba(0, 0, 0, 0.5); stroke-width: 1; transition: fill 0.12s; cursor: pointer; }
.kb.static .key path { cursor: default; }
.key.white path { fill: #f4f1ea; }
.key.black path { fill: #252321; stroke: #0e0d0c; }
.key .kl { font: 600 7px var(--font-sans); text-anchor: middle; fill: #6d6862; pointer-events: none; }
.key.black .kl { fill: #f1ece4; font-size: 5.5px; }
.key.down path { filter: brightness(0.85); }
.key.white.sel path { fill: color-mix(in oklab, var(--highlight) 55%, #f4f1ea); }
.key.black.sel path { fill: color-mix(in oklab, var(--highlight) 75%, #252321); }
.key.white.ok path { fill: color-mix(in oklab, var(--success) 55%, #f4f1ea); }
.key.black.ok path { fill: color-mix(in oklab, var(--success) 88%, #252321); }
.key.white.bad path { fill: color-mix(in oklab, var(--danger) 68%, #f4f1ea); }
.key.black.bad path { fill: color-mix(in oklab, var(--danger) 88%, #252321); }
.key.white.miss path { fill: color-mix(in oklab, var(--warning) 50%, #f4f1ea); }
.key.black.miss path { fill: color-mix(in oklab, var(--warning) 70%, #252321); }
.key.ok .kl, .key.bad .kl, .key.sel .kl, .key.miss .kl { fill: #1b1a19; font-size: 8px; }
.key.black.ok .kl, .key.black.bad .kl, .key.black.sel .kl, .key.black.miss .kl { fill: #fff; font-size: 6.5px; }

/* Round play button. */
.play-btn { display: inline-flex; align-items: center; gap: 0.55rem; padding: 0.7rem 1.3rem 0.7rem 1rem; min-height: 48px; border-radius: 999px; border: 1px solid color-mix(in oklab, var(--highlight) 55%, var(--border)); background: color-mix(in oklab, var(--highlight) 12%, transparent); color: var(--foreground); font: 600 1rem var(--font-sans); cursor: pointer; -webkit-tap-highlight-color: transparent; touch-action: manipulation; transition: background 0.15s, transform 0.08s; }
.play-btn:hover { background: color-mix(in oklab, var(--highlight) 20%, transparent); }
.play-btn:active { transform: scale(0.97); }
.play-btn:focus-visible { outline: none; box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring) 35%, transparent); }
.play-btn .ic { width: 1.3rem; height: 1.3rem; display: inline-flex; color: var(--highlight); }
.play-btn .ic svg { width: 100%; height: 100%; }
.play-btn.on .ic { animation: pulse 0.6s ease-in-out infinite alternate; }
.play-btn.small { padding: 0.45rem 0.95rem 0.45rem 0.75rem; min-height: 44px; font-size: 0.9rem; }
.play-btn.small .ic { width: 1rem; height: 1rem; }
@keyframes pulse { from { opacity: 1; } to { opacity: 0.35; } }

.cd-prompt { font-size: 1.05rem; }
.cd-chord { display: flex; align-items: baseline; gap: 0.9rem; flex-wrap: wrap; margin-top: -0.4rem; }
.cd-sym { font-size: 2.4rem; line-height: 1.1; }
.cd-name { color: var(--muted-foreground); font-size: 0.95rem; }
.cd-bar { display: flex; align-items: center; gap: 0.6rem; flex-wrap: wrap; }
.cd-bar .e-btn { min-height: 44px; }
.cd-count { font-size: 0.88rem; }
.cd-help { font-size: 0.82rem; margin: -0.5rem 0 0; }
.cd-row { display: flex; gap: 0.5rem; flex-wrap: wrap; }
.cd-tone { display: flex; flex-direction: column; align-items: center; gap: 0.15rem; min-width: 3.4rem; padding: 0.45rem 0.6rem; border-radius: calc(var(--radius) - 3px); border: 1px solid var(--border); }
.cd-tone .deg { font: 600 0.78rem var(--font-mono); color: var(--muted-foreground); }
.cd-tone .nm { font-size: 1.2rem; }
.cd-tone.ok { border-color: color-mix(in oklab, var(--success) 55%, var(--border)); background: color-mix(in oklab, var(--success) 10%, transparent); }
.cd-tone.miss { border-color: color-mix(in oklab, var(--warning) 70%, var(--border)); background: color-mix(in oklab, var(--warning) 12%, transparent); }
.cd-legend { display: flex; gap: 1rem; flex-wrap: wrap; font-size: 0.82rem; }
.cd-legend span { display: inline-flex; align-items: center; gap: 0.35rem; }
.cd-legend .sw { width: 0.85rem; height: 0.85rem; border-radius: 3px; display: inline-block; }
.cd-legend .sw.ok { background: color-mix(in oklab, var(--success) 70%, #252321); }
.cd-legend .sw.bad { background: color-mix(in oklab, var(--danger) 60%, #f4f1ea); }
.cd-legend .sw.miss { background: color-mix(in oklab, var(--warning) 60%, #f4f1ea); }

.sl-seq { display: flex; gap: 0.4rem; flex-wrap: wrap; min-height: 1.9rem; }
.sl-chip { display: inline-flex; align-items: center; justify-content: center; min-width: 1.9rem; height: 1.9rem; padding: 0 0.4rem; border-radius: 999px; border: 1px solid color-mix(in oklab, var(--highlight) 55%, var(--border)); background: color-mix(in oklab, var(--highlight) 12%, transparent); font: 600 0.85rem var(--font-mono); }
.cd-bar .e-btn { min-width: 44px; min-height: 44px; }
.cd-bar .play-btn.small { min-height: 44px; }

